import HTML from "@html/user-edit-page.html";
import ApplicationModel from "@core/ApplicationModel";
export default class EditUserPage extends HTMLElement {
    connectedCallback() {
        this.innerHTML = HTML;
        const currentUser = ApplicationModel.getInstance().get("currentUser");
        if (currentUser) {
            const userElement = this.querySelector('user-element');
            customElements.whenDefined('user-element').then(() => {
                userElement.update(currentUser);
            });
        }
    }
}
