import HTML from "@html/offer-page.html";
import OfferController from "@controllers/OfferController";
export default class OfferPage extends HTMLElement {
    connectedCallback() {
        this.innerHTML = HTML;
        const urlParams = new URLSearchParams(window.location.search);
        const offerID = parseInt(urlParams.get("id"));
        const offerElement = this.querySelector("offer-element");
        new OfferController(offerElement)
            .load(offerID);
    }
}
